INSERT INTO course (id, slug, title, subtitle, description, category, level, instructor, instructor_title, price, original_price, hours, rating, student_count, cover_key, badge, outcomes) VALUES
(1, 'angular-thuc-chien', 'Angular từ cơ bản đến thực chiến', 'Tự tay xây dựng ứng dụng web hiện đại với Angular.', 'Bắt đầu từ những khái niệm nền tảng, làm quen với component, routing và kết nối API. Lộ trình hướng đến việc xây dựng một ứng dụng có cấu trúc rõ ràng và dễ mở rộng.', 'Lập trình', 'Cơ bản', 'Nguyễn Minh Anh', 'Frontend Developer · 8 năm kinh nghiệm', 599000, 1299000, 1.2, 4.9, 1240, 'angular', 'Được yêu thích', 'Hiểu component và cấu trúc dự án Angular|Quản lý dữ liệu với signals và services|Xây dựng biểu mẫu và định tuyến|Kết nối ứng dụng với REST API'),
(2, 'ui-ux-figma', 'UI/UX Design: Từ ý tưởng đến sản phẩm', 'Biến ý tưởng thành trải nghiệm số đáng nhớ.', 'Khám phá tư duy thiết kế lấy người dùng làm trung tâm. Thực hành từ bố cục, màu sắc đến hệ thống component và prototype tương tác trên Figma.', 'Thiết kế', 'Cơ bản', 'Trần Hà Linh', 'Product Designer · 6 năm kinh nghiệm', 499000, 999000, 1.1, 4.8, 860, 'figma', 'Bán chạy', 'Nắm vững quy trình thiết kế sản phẩm|Sử dụng Auto Layout trong Figma|Tạo hệ thống component nhất quán|Xây dựng prototype và kiểm thử ý tưởng'),
(3, 'java-spring-boot', 'Java Spring Boot: Xây dựng REST API', 'Xây dựng backend vững chắc cho sản phẩm của bạn.', 'Tìm hiểu cách tổ chức backend theo các lớp controller, service và repository. Kết nối MySQL, xây dựng API và bổ sung xác thực cho ứng dụng Java.', 'Lập trình', 'Trung cấp', 'Lê Hoàng Nam', 'Backend Engineer · 10 năm kinh nghiệm', 699000, 1499000, 1.4, 4.9, 720, 'java', 'Mới cập nhật', 'Thiết kế REST API với Spring Boot|Kết nối và thao tác dữ liệu MySQL|Xác thực người dùng với Spring Security|Tổ chức mã nguồn theo từng tính năng'),
(4, 'python-co-ban', 'Python: Bắt đầu hành trình lập trình', 'Viết những dòng code đầu tiên thật tự tin.', 'Làm quen với biến, kiểu dữ liệu, vòng lặp và hàm qua những ví dụ dễ tiếp cận. Từng bước hình thành tư duy lập trình và tự động hóa công việc nhỏ mỗi ngày.', 'Lập trình', 'Cơ bản', 'Phạm Thu Hà', 'Software Engineer · 5 năm kinh nghiệm', 399000, 799000, 1.0, 4.8, 1560, 'python', NULL, 'Viết chương trình Python đầu tiên|Sử dụng điều kiện và vòng lặp|Tổ chức chương trình bằng hàm|Xử lý dữ liệu và tự động hóa tác vụ'),
(5, 'digital-marketing', 'Digital Marketing cho người mới', 'Đưa thương hiệu đến đúng người, đúng thời điểm.', 'Xây dựng nền tảng marketing số với nội dung, kênh truyền thông và cách đọc chỉ số. Thực hành lập kế hoạch cho một chiến dịch có mục tiêu rõ ràng.', 'Marketing', 'Cơ bản', 'Đỗ Khánh Vy', 'Marketing Strategist · 7 năm kinh nghiệm', 449000, 899000, 1.1, 4.7, 640, 'marketing', NULL, 'Xác định khách hàng và thông điệp|Xây dựng kế hoạch nội dung|Lựa chọn kênh truyền thông phù hợp|Đọc chỉ số và tối ưu chiến dịch'),
(6, 'illustrator-sang-tao', 'Illustrator: Đánh thức sáng tạo', 'Từ nét vẽ đầu tiên đến thiết kế mang dấu ấn riêng.', 'Khám phá thiết kế vector với hình khối, màu sắc và typography. Thực hành tạo hình minh họa và các sản phẩm đồ họa có thể ứng dụng trong thực tế.', 'Thiết kế', 'Cơ bản', 'Vũ Đức Anh', 'Visual Designer · 6 năm kinh nghiệm', 499000, 1099000, 1.0, 4.8, 480, 'illustrator', NULL, 'Sử dụng công cụ thiết kế vector|Kết hợp hình khối và màu sắc|Làm việc với chữ và bố cục|Xuất sản phẩm cho web và in ấn');
